CREATE TYPE "GovernancePolicyStatus" AS ENUM ('DRAFT','REVIEW','APPROVED','ACTIVE','SUPERSEDED','RETIRED');
CREATE TYPE "GovernanceDecision" AS ENUM ('ALLOW','REVIEW','BLOCK');
CREATE TYPE "GovernanceDisputeState" AS ENUM ('OPEN','EVIDENCE_COLLECTION','AI_TRIAGE','HUMAN_REVIEW','DECISION','APPEAL','RESOLUTION','CLOSED','CANCELLED','REJECTED');
CREATE TYPE "PrivacyRequestState" AS ENUM ('SUBMITTED','IDENTITY_VERIFICATION','IN_REVIEW','APPROVED','PROCESSING','COMPLETED','REJECTED','CANCELLED');
CREATE TYPE "ConsentStatus" AS ENUM ('GRANTED','WITHDRAWN');
CREATE TYPE "EnforcementActionState" AS ENUM ('PROPOSED','REVIEW','ACTIVE','LIFTED','EXPIRED','CANCELLED');
CREATE TABLE "GovernancePolicy" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"key" TEXT NOT NULL,"scope" TEXT NOT NULL,"level" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GovernancePolicy_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "GovernancePolicy_businessId_key_key" ON "GovernancePolicy"("businessId","key"); CREATE INDEX "GovernancePolicy_businessId_marketId_scope_idx" ON "GovernancePolicy"("businessId","marketId","scope");
CREATE TABLE "GovernancePolicyVersion" ("id" TEXT PRIMARY KEY,"policyId" TEXT NOT NULL,"version" INTEGER NOT NULL,"status" "GovernancePolicyStatus" NOT NULL DEFAULT 'DRAFT',"failMode" TEXT NOT NULL,"rules" JSONB NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveUntil" TIMESTAMP(3),"createdBy" TEXT NOT NULL,"reason" TEXT NOT NULL,"metadata" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GovernancePolicyVersion_policyId_fkey" FOREIGN KEY ("policyId") REFERENCES "GovernancePolicy"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "GovernancePolicyVersion_policyId_version_key" ON "GovernancePolicyVersion"("policyId","version"); CREATE INDEX "GovernancePolicyVersion_policyId_status_effectiveFrom_effectiveUntil_idx" ON "GovernancePolicyVersion"("policyId","status","effectiveFrom","effectiveUntil");
CREATE TABLE "PolicyEvaluation" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"scope" TEXT NOT NULL,"policyVersionId" TEXT NOT NULL,"ruleKey" TEXT,"inputSnapshot" JSONB NOT NULL,"decision" "GovernanceDecision" NOT NULL,"reasonCode" TEXT NOT NULL,"deterministicKey" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"actorId" TEXT NOT NULL,"correlationId" TEXT NOT NULL,"aiMetadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PolicyEvaluation_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT,CONSTRAINT "PolicyEvaluation_policyVersionId_fkey" FOREIGN KEY ("policyVersionId") REFERENCES "GovernancePolicyVersion"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "PolicyEvaluation_businessId_idempotencyKey_key" ON "PolicyEvaluation"("businessId","idempotencyKey"); CREATE INDEX "PolicyEvaluation_businessId_scope_decision_createdAt_idx" ON "PolicyEvaluation"("businessId","scope","decision","createdAt"); CREATE INDEX "PolicyEvaluation_deterministicKey_idx" ON "PolicyEvaluation"("deterministicKey");
CREATE TABLE "HumanOverride" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"evaluationId" TEXT NOT NULL,"previousDecision" "GovernanceDecision" NOT NULL,"newDecision" "GovernanceDecision" NOT NULL,"reason" TEXT NOT NULL,"actorId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HumanOverride_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT,CONSTRAINT "HumanOverride_evaluationId_fkey" FOREIGN KEY ("evaluationId") REFERENCES "PolicyEvaluation"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "HumanOverride_businessId_idempotencyKey_key" ON "HumanOverride"("businessId","idempotencyKey"); CREATE INDEX "HumanOverride_businessId_evaluationId_createdAt_idx" ON "HumanOverride"("businessId","evaluationId","createdAt");
CREATE TABLE "GovernanceDispute" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"category" TEXT NOT NULL,"reason" TEXT NOT NULL,"parties" JSONB NOT NULL,"evidenceMetadata" JSONB NOT NULL,"state" "GovernanceDisputeState" NOT NULL DEFAULT 'OPEN',"idempotencyKey" TEXT NOT NULL,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GovernanceDispute_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "GovernanceDispute_businessId_idempotencyKey_key" ON "GovernanceDispute"("businessId","idempotencyKey"); CREATE INDEX "GovernanceDispute_businessId_state_createdAt_idx" ON "GovernanceDispute"("businessId","state","createdAt");
CREATE TABLE "DisputeTransition" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"disputeId" TEXT NOT NULL,"fromState" "GovernanceDisputeState" NOT NULL,"toState" "GovernanceDisputeState" NOT NULL,"reason" TEXT NOT NULL,"actorId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"metadata" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DisputeTransition_disputeId_fkey" FOREIGN KEY ("disputeId") REFERENCES "GovernanceDispute"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "DisputeTransition_businessId_idempotencyKey_key" ON "DisputeTransition"("businessId","idempotencyKey"); CREATE INDEX "DisputeTransition_businessId_disputeId_createdAt_idx" ON "DisputeTransition"("businessId","disputeId","createdAt");
CREATE TABLE "GovernanceAppeal" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"disputeId" TEXT NOT NULL,"grounds" TEXT NOT NULL,"evidenceMetadata" JSONB NOT NULL,"status" TEXT NOT NULL,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resolvedAt" TIMESTAMP(3),CONSTRAINT "GovernanceAppeal_disputeId_fkey" FOREIGN KEY ("disputeId") REFERENCES "GovernanceDispute"("id") ON DELETE RESTRICT); CREATE INDEX "GovernanceAppeal_businessId_disputeId_status_idx" ON "GovernanceAppeal"("businessId","disputeId","status");
CREATE TABLE "ConsentRecord" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"purpose" TEXT NOT NULL,"noticeVersion" TEXT NOT NULL,"status" "ConsentStatus" NOT NULL,"grantedAt" TIMESTAMP(3),"withdrawnAt" TIMESTAMP(3),"actorId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ConsentRecord_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "ConsentRecord_businessId_idempotencyKey_key" ON "ConsentRecord"("businessId","idempotencyKey"); CREATE INDEX "ConsentRecord_businessId_subjectId_purpose_createdAt_idx" ON "ConsentRecord"("businessId","subjectId","purpose","createdAt");
CREATE TABLE "PrivacyRequest" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"type" TEXT NOT NULL,"state" "PrivacyRequestState" NOT NULL DEFAULT 'SUBMITTED',"idempotencyKey" TEXT NOT NULL,"requestedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "PrivacyRequest_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "PrivacyRequest_businessId_idempotencyKey_key" ON "PrivacyRequest"("businessId","idempotencyKey"); CREATE INDEX "PrivacyRequest_businessId_state_createdAt_idx" ON "PrivacyRequest"("businessId","state","createdAt");
CREATE TABLE "PrivacyRequestTransition" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"requestId" TEXT NOT NULL,"fromState" "PrivacyRequestState" NOT NULL,"toState" "PrivacyRequestState" NOT NULL,"reason" TEXT NOT NULL,"actorId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PrivacyRequestTransition_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "PrivacyRequest"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "PrivacyRequestTransition_businessId_idempotencyKey_key" ON "PrivacyRequestTransition"("businessId","idempotencyKey"); CREATE INDEX "PrivacyRequestTransition_businessId_requestId_createdAt_idx" ON "PrivacyRequestTransition"("businessId","requestId","createdAt");
CREATE TABLE "RetentionPolicy" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"recordClass" TEXT NOT NULL,"version" INTEGER NOT NULL,"retentionDays" INTEGER NOT NULL,"action" TEXT NOT NULL,"protected" BOOLEAN NOT NULL DEFAULT false,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveUntil" TIMESTAMP(3),"createdBy" TEXT NOT NULL,CONSTRAINT "RetentionPolicy_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "RetentionPolicy_businessId_recordClass_version_key" ON "RetentionPolicy"("businessId","recordClass","version"); CREATE INDEX "RetentionPolicy_businessId_marketId_recordClass_effectiveFrom_idx" ON "RetentionPolicy"("businessId","marketId","recordClass","effectiveFrom");
CREATE TABLE "EnforcementAction" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"subjectType" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"type" TEXT NOT NULL,"state" "EnforcementActionState" NOT NULL DEFAULT 'PROPOSED',"reasonCodes" TEXT[],"policyEvaluationId" TEXT,"financialReference" TEXT,"startsAt" TIMESTAMP(3),"endsAt" TIMESTAMP(3),"actorId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EnforcementAction_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "EnforcementAction_businessId_idempotencyKey_key" ON "EnforcementAction"("businessId","idempotencyKey"); CREATE INDEX "EnforcementAction_businessId_subjectType_subjectId_state_idx" ON "EnforcementAction"("businessId","subjectType","subjectId","state");
CREATE TABLE "GovernanceEvent" ("id" TEXT PRIMARY KEY,"eventId" TEXT NOT NULL,"businessId" TEXT NOT NULL,"marketId" TEXT NOT NULL,"type" TEXT NOT NULL,"actorId" TEXT,"resourceType" TEXT NOT NULL,"resourceId" TEXT NOT NULL,"correlationId" TEXT NOT NULL,"payload" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GovernanceEvent_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "GovernanceEvent_eventId_key" ON "GovernanceEvent"("eventId"); CREATE INDEX "GovernanceEvent_businessId_type_createdAt_idx" ON "GovernanceEvent"("businessId","type","createdAt"); CREATE INDEX "GovernanceEvent_marketId_type_createdAt_idx" ON "GovernanceEvent"("marketId","type","createdAt");
